// Calculate booked orders (false branch - not processing)
const orders = data.orders || [];
let totalBooked = 0;
let bookedSum = 0;

for (let order of orders) {
  if (order.orderStatus === 'booked') {
    totalBooked++;
    bookedSum += order.orderPrice;
  }
}

return {
  ...data,
  totalBooked: totalBooked,
  bookedSum: bookedSum,
  message: `This week we have ${totalBooked} booked orders with a total value of $${bookedSum}`
};

// Filter processing orders (true branch)
const orders = data.orders || [];
const processingOrders = orders.filter(order => order.orderStatus === 'processing');

console.log(`Found ${processingOrders.length} processing orders`);

return {
  ...data,
  processingOrders: processingOrders,
  processingCount: processingOrders.length
};
